corrected_code:
const exportSnapshotSchema = {
  params: {
    type: 'object',
    required: ['snapshotId'],
    properties: {
      snapshotId: { type: 'string', pattern: '^snap-[a-f0-9]{12}$' }
    }
  }
};

fastify.post('/api/backups/snapshots/:snapshotId/export', {
  schema: exportSnapshotSchema,
  onRequest: [fastify.verifySession]
}, async (request, reply) => {
  const { snapshotId } = request.params;

  const meta = await db.query(
    'SELECT id FROM tenant_snapshots WHERE snapshot_id = $1 AND tenant_id = $2',
    [snapshotId, request.user.tenantId]
  );
  if (meta.rowCount === 0) {
    return reply.status(403).send({ message: 'Access denied to requested database snapshot' });
  }

  const snapshot = await rdsClient.describeDBSnapshots({
    DBSnapshotIdentifier: snapshotId
  });
  if (!snapshot.DBSnapshots?.length) {
    return reply.status(404).send({ message: 'Snapshot not found' });
  }

  const exportTask = await rdsClient.startExportTask({
    ExportTaskIdentifier: `export-${Date.now()}`,
    SourceArn: snapshot.DBSnapshots[0].DBSnapshotArn,
    S3BucketName: process.env.PUBLIC_BACKUPS_BUCKET
  });

  return reply.send({ taskId: exportTask.ExportTaskIdentifier, status: 'started' });
});
